import 'dart:io';

String replaceAll(String source, String search, String replacement) {
  int index = 0;
  List<String> resultParts = [];

  while (true) {
    int foundIndex = source.indexOf(search, index);

    if (foundIndex == -1) {
      break; 

    } else {
      if (foundIndex > index) {
        resultParts.add(source.substring(index, foundIndex));

      }

      resultParts.add(replacement);
      index = foundIndex + search.length;
    }
  }

  if (index < source.length) {
    resultParts.add(source.substring(index));
  }

  return resultParts.join('');
}

