    if (root == null) {
      root = new Node(key);
      return;
    }
    var node = _insert(root, key);
    _rebalance(node);
  }

  Node _insert(Node node, int key) {
    if (node == null) {
      return new Node(key);
    }
    if (key < node.key) {
      node.left = _insert(node.left, key);
    } else if (key > node.key) {
      node.right = _insert(node.right, key);
    } else {
      return node; // Duplicate keys are not allowed.
    }
    return node;
  }

  void _rebalance(Node node) {
    while (true) {
      if (_isRed(node.left) && _isRed(node.left.left)) {
        _rightRotate(node);
      }
      if (_isRed(node.right) && _isRed(node.right.right)) {
        _leftRotate(node);
      }
      if (_isRed(node.left) && _isRed(node.right)) {
        _flipColors(node);
      }
      if (!_isRed(node.left) && !_isRed(node.right)) {
        break;
      }
      node = node.parent;
    }
  }

  bool _isRed(Node node) => node != null ? node.color == 'red' : false;

  void _rightRotate(Node y) {
    var x = y.left;
    y.left = x.right;
    if (x.right != null) {
      x.right.parent = y;
    }
    x.parent = y.parent;
    if (y.parent == null) {
      root = x;
    } else if (y == y.parent.left) {
      y.parent.left = x;
    } else {
      y.parent.right = x;
    }
    x.right = y;
    y.parent = x;
  }

  void _leftRotate(Node x) {
    var y = x.right;
    x.right = y.left;
    if (y.left != null) {
      y.left.parent = x;
    }
    y.parent = x.parent;
    if (x.parent == null) {
      root = y;
    } else if (x == x.parent.left) {
      x.parent.left = y;
    } else {
      x.parent.right = y;
    }
    y.left = x;
    x.parent = y;
  }

  void _flipColors(Node node) {
    node.color = 'black';
    node.left!.color = 'red';
    node.right!.color = 'red';
  }

  void printInOrder() {
    _printInOrder(root);
    print();
  }

