class Graph {
  final Map<int, Set<int>> adjacencyList = {};

  void addEdge(int src, int dest) {
    if (!adjacencyList.containsKey(src)) {
      adjacencyList[src] = {};
    }
    if (!adjacencyList.containsKey(dest)) {
      adjacencyList[dest] = {};
    }
    adjacencyList[src]!.add(dest);
    adjacencyList[dest]!.add(src); // For undirected graph
  }

  bool hasCycle() {
    final visited = <int>{};

    for (final vertex in adjacencyList.keys) {
      if (!visited.contains(vertex) && _dfsHasCycle(vertex, {}, visited)) {
        return true;
      }
    }
    return false;
  }

  bool _dfsHasCycle(int node, Set<int>? path, Set<int> visited) {
    visited.add(node);
    path ??= {};
    path.add(node);

    if (adjacencyList[node]?.contains(path.first) == true) {
      return true;
    }

    for (final neighbor in adjacencyList[node] ?? {}) {
      if (!path.contains(neighbor)) {
        if (_dfsHasCycle(neighbor, path, visited)) {
          return true;
        }
      } else if (path.contains(neighbor)) {
        return true;
      }
    }

    path.remove(node);
    return false;
  }
}


