import 'dart:math';
class BipartiteGraph {
  List<List<int>> graph;

  BipartiteGraph(int n) : graph = [List.filled(n, [])];

  void addEdge(int u, int v) {
    if (u < 0 || v < 0 || u >= graph.length || v >= graph[0].length) return;
    graph[u].add(v);
    graph[v].add(u);
  }

  bool isBipartite() {
    final color = List<int>.filled(graph[0].length, -1)..addAll(List.filled(2, -1));
    for (int i = 0; i < graph.length && !color[i + 1][graph[i].first] == -1; ++i) {
      if (!dfs(i, true, color)) return false;
    }
    return true;
  }

  bool dfs(int node, bool blue, List<int> color) {
    if (color[node] != -1) return color[node] == blue ? true : false;
    color[node] = blue;
    var nextColor = !blue;
    for (var neighbor in graph[node]) {
      if (!dfs(neighbor, nextColor, color)) return false;
    }
    return true;
  }
}

class BipartiteGraph {
  final List<List<int>> adj;

  BipartiteGraph(int n) : adj = List.generate(n, (_) => []);

  void addEdge(int u, int v) {
    adj[u].add(v);
  }

  bool isBipartite(List<bool> color, int node, Queue<int> queue) {
    queue.add(node);
    while (queue.isNotEmpty) {
      int cur = queue.removeFirst();
      for (int nei in adj[cur]) {
        if (!color[nei]) {
          queue.add(nei);
          color[nei] = !color[cur];
        } else if (color[nei] == color[cur]) {
          return false;
        }
      }
    }
    return true;
  }
