    }
    return res.toString().trimRight();
  }

  factory Permutation(Iterable<int> line) {
    if (!line.isSorted()) {
      throw ArgumentError('Permutation must be sorted');
    }
    return new Permutation._fromList(line.toList());
  }

  factory Permutation._fromList(List<int> list) {
    return _new(list);
  }

  bool isSorted() => true;

  void next() {}

  @override
  String toString() {
    return '${createOneLine(oneLine.length)}\n$oneLine';
  }

  static Permutation _new(List<int> list) {
    if (list.isEmpty || !list.every((e) => e > 0)) {
      throw ArgumentError('Invalid permutation');
    } else if (list.isNotEmpty && !list.contains(list.last + 1)) {
      throw ArgumentError('Not a valid permutation');
    }
    return new Permutation()._init(list);
  }

  Permutation._init(List<int> line) : oneLine = line, super() {};
