    if (a.length != b.length || a[0].length != b[0].length) return false;

    for (var row in a) {
      for (var col in row) {
        if (!b.any((innerRow) => innerRow.contains(col))) return false;

        bool foundMatch = false;
        for (var innerRow in b) {
          if (innerRow.indexWhere((element) => element == col) >= 0) {
            foundMatch = true;
            break;
          }
        }
        if (!foundMatch) return false;
      }
    }
    return true;
  }


