List<Vector> convexHull(List<Vector> points) {
  if (points.length <= 1) return points;

  int n = points.length;
  List<int> hullIndices = [];
  bool onHull = <int>[];
  for (int i = 0; i < n; i++) onHull.add(false);

  // Find the point with minimum y-coordinate (and leftmost in case of tie)
  int minYIndex = 0;
  for (int i = 1; i < n; i++) {
    if (points[i].y < points[minYIndex].y ||
        (points[i].y == points[minYIndex].y && points[i].x < points[minYIndex].x)) {
      minYIndex = i;
    }
  }

  int start = minYIndex;
  int next = (start + 1) % n;
  while (true) {
    onHull[start] = true;
    hullIndices.add(start);
    int candidate = next;
    for (int i = 0; i < n; i++) {
      if (!onHull[i]) {
        if (isLeftTurn(points[next], points[candidate], points[i])) {
          candidate = i;
        } else if (isLeftTurn(points[next], points[candidate], points[i]) == false &&
            !isLeftTurn(points[next], points[candidate], points[i])) {
          continue;
        }
      }
    }
    next = candidate;
    if (next == start) break;
    start = next;
  }

  return hullIndices.map((i) => points[i]).toList();
}

