double distancePointLine(Vector point, Vector lineStart,
        Vector lineEnd) {

  if (lineStart == null || lineEnd == null) {
    throw ArgumentError("Vector cannot be null.");
  }


  final delta = lineStart.subtract(lineEnd);
  double dotProd = delta.dot(point.subtract(lineStart));


  final lenSqDelta = delta.lengthSquared();
  var t = dotProd / lenSqDelta;


  if (t < 0.0) {
    return Math.sqrt(point.distanceSquared(lineStart));
  } else if (t > 1.0) {
    return Math.sqrt(point.distanceSquared(lineEnd));
  }

  final projection = lineStart.add(delta.multiply(t));
  return point.distance(projection);
}

