    }
    x1 = result.x;
    x2 = p - x1;
    if (multiplyModulus(x1, x1, p) == n && multiplyModulus(x2, x2, p) == n) {
      print("Square roots of $n are ($x1 and $x2) mod $p\n");
      return;
    }
