  int hashCode => Object.hash(_x, _y);


  @override
  bool operator ==(Object other) => other is Fp2 && ((_x - other._x) & (modulus - 1)) == 0 && ((_y - other._y) & (modulus - 1)) == 0;


  Fp2 negate() => Fp2(modulus - _x, modulus - _y);


  Fp2 conjugate() => Fp2(x, (-_y + modulus) % modulus);


  Fp2 add(Fp2 other) => Fp2((_x + other.x) % modulus, (_y + other.y) % modulus);


  Fp2 sub(Fp2 other) => Fp2((_x - other.x + modulus) % modulus, (_y - other.y + modulus) % modulus);


  Fp2 mul(Fp2 other) {
    var r = (((_x * other.x + _y * other.y) % modulus), 
             ((-_x * other.y - _y * other.x) % modulus));
    return Fp2(r.first, r.second);
  }


  Fp2 div(Fp2 other) => Fp2(other.conjugate()) * multiplyFp2().mul(other);
}

