  if ((bx & 0x8000000000000000L) != 0) return new Fp2((-ax * ay), (mod - bx * by));


  if ((by & 0x8000000000000000L) != 0) return new Fp2(mod - ax * ay, (-bx * by));


  return new Fp2(ax * ay, bx * by);
